from collections import deque
from typing import List

def maximizeStellarGradient(n: int, edges: List[List[int]]) -> int:
    # edges[k] = [u, v, b]：b = 1 表示 e_v = e_u + 1；b = 0 表示方向未知（|e_u - e_v| = 1）
    INF = float('inf')
    d = [[INF] * (n + 1) for _ in range(n + 1)]
    adj = [[] for _ in range(n + 1)]
    for i in range(1, n + 1):
        d[i][i] = 0
    for u, v, b in edges:
        adj[u].append(v); adj[v].append(u)
        if b == 1:
            d[u][v] = min(d[u][v], 1)       # e_v - e_u <= 1
            d[v][u] = min(d[v][u], -1)      # e_u - e_v <= -1
        else:
            d[u][v] = min(d[u][v], 1)
            d[v][u] = min(d[v][u], 1)

    # 每条边两端奇偶性必须不同：图必须是二分图
    color = [-1] * (n + 1)
    for s in range(1, n + 1):
        if color[s] != -1:
            continue
        color[s] = 0
        dq = deque([s])
        while dq:
            u = dq.popleft()
            for w in adj[u]:
                if color[w] == -1:
                    color[w] = color[u] ^ 1
                    dq.append(w)
                elif color[w] == color[u]:
                    return -1

    # 差分约束：Floyd 求所有点对最短路
    for k in range(1, n + 1):
        dk = d[k]
        for i in range(1, n + 1):
            dik = d[i][k]
            if dik == INF:
                continue
            di = d[i]
            for j in range(1, n + 1):
                if dik + dk[j] < di[j]:
                    di[j] = dik + dk[j]
    if any(d[i][i] < 0 for i in range(1, n + 1)):
        return -1
    # 以 s 为最小值点时 e_j = d[s][j]，差距为 max_j d[s][j]
    return max(max(d[s][1:]) for s in range(1, n + 1))
